import React, { useRef, useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { StyledPageContainer, PageContent, SocialMediaSection } from './Pages.styles';
import Tagline from '../components/Tagline/Tagline';
import KimeraVision from '../components/KimeraVision/KimeraVision';
import { KimeraVisionRef } from '../components/KimeraVision/KimeraVision.types';
import KimeraWareSocialMedia from '../components/KimeraWareSocialMedia/KimeraWareSocialMedia';
import LearnMore from '../components/LearnMore/LearnMore';
import { SEO } from '../components/SEO/SEO';
import { StructuredData } from '../components/StructuredData/StructuredData';
import { STRUCTURED_DATA } from '../constants/seo.constants';

const HomePage: React.FC = () => {
  const { t } = useTranslation();
  const kimeraVisionRef = useRef<KimeraVisionRef>(null);
  const keySequenceRef = useRef<string>('');
  const timeoutRef = useRef<number | null>(null);

  useEffect(() => {
    const handleKeyPress = (event: KeyboardEvent) => {
      const key = event.key.toUpperCase();

      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }

      const newSequence = keySequenceRef.current + key;

      if ('TUMAMA'.startsWith(newSequence)) {
        keySequenceRef.current = newSequence;

        if (newSequence === 'TUMAMA') {
          if (kimeraVisionRef.current) {
            kimeraVisionRef.current.triggerEasterEgg();
          }
          keySequenceRef.current = '';
        } else {
          timeoutRef.current = window.setTimeout(() => {
            keySequenceRef.current = '';
          }, 2000);
        }
      } else {
        keySequenceRef.current = '';
      }
    };

    window.addEventListener('keydown', handleKeyPress);

    return () => {
      window.removeEventListener('keydown', handleKeyPress);
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, []);

  return (
    <StyledPageContainer id="home">
      <SEO
        title={t('seo.home.title')}
        description={t('seo.home.description')}
        keywords={t('seo.home.keywords')}
        canonicalUrl="/"
        type="website"
      />
      <StructuredData data={STRUCTURED_DATA.ORGANIZATION} />
      <Tagline />
      <KimeraVision ref={kimeraVisionRef} />
      <PageContent>
        <LearnMore />
        <SocialMediaSection>
          <div>
            <KimeraWareSocialMedia />
          </div>
        </SocialMediaSection>
      </PageContent>
    </StyledPageContainer>
  );
};

export default HomePage;
